export function installSpotlights(){document.querySelectorAll('.spotlight').forEach(el=>el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.setProperty('--mx',`${e.clientX-r.left}px`);el.style.setProperty('--my',`${e.clientY-r.top}px`)}))}
export function installMagnets(){if(matchMedia('(prefers-reduced-motion: reduce)').matches||matchMedia('(pointer: coarse)').matches)return;document.querySelectorAll('.magnet').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.08}px,${(e.clientY-r.top-r.height/2)*.08}px)`});el.addEventListener('pointerleave',()=>el.style.transform='')})}
export function decryptText(el,text){if(matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=text;return}const chars='01<>/[]{}*#';let frame=0;const max=Math.min(18,Math.max(8,text.length));const timer=setInterval(()=>{el.textContent=[...text].map((c,i)=>i<Math.floor(frame/max*text.length)?c:(c===' '?' ':chars[Math.floor(Math.random()*chars.length)])).join('');frame++;if(frame>max){clearInterval(timer);el.textContent=text}},24)}
